import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageSubjects() {
  const [subjects, setSubjects] = useState([]);
  const [subjectName, setSubjectName] = useState('');

  // Database එකේ තියෙන විෂයයන් ටික ගන්නවා
  const fetchSubjects = () => {
    axios.get('http://localhost:8081/api/view-subjects')
      .then(res => setSubjects(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => {
    fetchSubjects();
  }, []);

  // අලුත් විෂයයක් සේව් කරනවා
  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/add-subject', { subject_name: subjectName })
      .then(() => {
        fetchSubjects(); // සේව් වුණාම ලිස්ට් එක අලුත් කරනවා
        setSubjectName(''); // කොටුව ආයෙත් හිස් කරනවා
        alert("Subject Added Successfully!");
      })
      .catch(err => alert("Error adding subject!"));
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif', animation: 'fadeIn 0.5s' }}>
      <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', marginBottom: '20px' }}>
        <h2 style={{ margin: '0 0 20px 0', color: '#15803d' }}>📚 Manage Subjects</h2>
        
        <form onSubmit={handleSubmit} style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
          <input 
            type="text" 
            placeholder="Enter Subject Name (e.g. History)" 
            value={subjectName} 
            onChange={(e) => setSubjectName(e.target.value)} 
            required 
            style={{ padding: '12px', width: '300px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none' }}
          />
          <button type="submit" style={{ padding: '12px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>
            + Add Subject
          </button>
        </form>
      </div>

      <div style={{ backgroundColor: '#fff', borderRadius: '12px', overflow: 'hidden', width: '60%' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={{ padding: '15px', color: '#475569' }}>ID</th>
              <th style={{ padding: '15px', color: '#475569' }}>Subject Name</th>
            </tr>
          </thead>
          <tbody>
            {subjects.map((s) => (
              <tr key={s.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{ padding: '15px', fontWeight: 'bold', color: '#94a3b8' }}>{s.id}</td>
                <td style={{ padding: '15px', fontWeight: 'bold', color: '#333' }}>{s.subject_name}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
